    enoaLead: ["Вы выбрались из рудников, местоположение которых скрывали даже от тех, кто годами работал внизу. В неволе вы разбивали породу, переносили груз и учились различать по звуку, где держит камень, а где следует отойти. Скудный свет заставлял беречь движения, а надзор — замечать смену караула и искать тихие пути между выработками. Работа укрепила тело и дала знание камня, которое позднее пригодилось с настоящими инструментами каменщика. Побег не оставил готовой карты, зато научил рассчитывать силы на долгий путь. Как пережитое сказалось на вашем отношении к людям и чего вы искали на свободе, решали вы сами."],
    loreContext: ["Никто не знает, где эти чёртовы рудники. Везут с мешком на голове; четверо суток, может, шестеро — считаешь не вёрсты, а остановки. Из места, которого нет на карте, не выкупают.","Сидят там за всё: за надпись на стене храма Белых Отцов и за годы убийств. Через месяц не отличить, кто из них кто.","Три уровня. Наверху дангунцы считают телеги, посередине худдулины гонят руду и бьют тех, кто ниже, на дне добывают все остальные. Сверху вниз идут приказы, снизу вверх — руда. Еда до дна не доходит.","Поэтому на дне едят друг друга. Второй уровень знает и не мешает. Первый заносит в книгу: естественная убыль.","В ком проступает сила, тому надевают обруч на камне из Дангуна, и внутри становится тихо. Те, кому своё потом вернули, говорят, что тишина была хуже голода. Говорят уже наверху, где есть время подбирать слова.","Оттуда не выходил никто — это не присказка, а запись в книгах. Вы вышли, и тогда выяснилось худшее: вы не знаете, откуда шли, а значит, не знаете, куда идти прочь. Вы шли, пока земля не поменяла цвет. Спустя годы вы всё ещё просыпаетесь первым и смотрите назад."],
