    play: "Атлетика со Скрытностью — «копать и не попадаться», и в подземельях это работает буквально: побег был первым подземельем персонажа. «Крепкий» отыгрывает пережитую яму, инструменты каменщика читают и вскрывают породу. Уровень задаёт не силу персонажа, а его прошлое и то, кому он там был врагом: с третьего уровня помнят руки второго, а второй помнит, чьи распоряжения приходили с первого. Мастеру: побег — событие, которого по официальной версии не было, и это ценнее любого бонуса; одни сочтут персонажа вруном, другие захотят узнать способ, третьи вернут его вниз. Отдельно про третий уровень: там едят людей, и это стоит проговорить на нулевой сессии — как далеко персонаж зашёл и хочет ли стол вообще про это играть. Диадема остаётся сюжетным предметом и механически не даёт и не отнимает ничего. Отличный старт для варвара, монаха и любого заклинателя, которому нужна причина бояться собственной силы."
