        'Юрта огня, степи Хурхона',
        'Огонь очищает, и в юрте огня золотой чай подаёт чайомант: здесь не нарушают ни одного закона, и даже Великий Агха не бросит ему вызов, чтобы не навлечь проклятие Солнца. Вы платили кайуком за вход, окунались в морозную бочку, чтобы не опозориться, и выучили заварку эрхов — семь вдохов, бросок шагая, подать раскалённым, словно сам Шамас. Нарушить правило юрты равносильно смерти, и вы видели, как это выглядит.'
