    play: "«Лекарь» превращает Набор лекаря в устойчивое лечение вне боя; описывать его можно настоями, припарками, маслами и травами чайных мастеров — это подача, механику черты она не меняет. Проницательность с Медициной дают персонажа, который читает гостя и понимает, что ему нужно: совет, лекарство или ещё одна пиала. Набор травника покрывает и чайное знание — лист, коренья, цветы и пряности разных народов, — и им же удобно заваривать чаи из раздела «Чай» проверкой инструмента против Сложности создания. Хорош для жреца Ира, друида и барда."
