    glossary: ['ability-check-phb', 'prone-phb', 'push-phb'],
    enoaLead: ["Вы учились в цехе мастеров, почитавших Гендина, Великого Строителя. День начинался с подготовки огня и инструментов, затем следовали повторные удары, проверка заготовки и исправление того, что наставник не принимал. Вы поднимали тяжёлый материал, выдерживали жар и учились видеть причину трещины раньше, чем она портила изделие. Мелкая отделка требовала точных рук, расчёт — ясной головы, а длинная работа — терпения. Вы перенимали привычку делать надёжно и не скрывать ошибку под украшением. Собственные замыслы могли быть скромными или великими; предыстория давала опыт ученика, а не заранее обещанное место среди легендарных мастеров."],
    loreContext: ["Кузнецы, каменщики и зодчие Даскара чтут Гендина — звезду созидания, Великого Строителя, что сформировал горы и разместил континенты. Он никогда не спешит: удар за ударом молотом Граном на наковальне Чаре он медленно придаёт миру новую форму и вечно удерживает его в ней. Каждое утро в цехах Строителя жгут масло, чтобы смягчить его замах, а потом берутся за работу, которой хватит на века: стены, что переживут города, мосты над пропастями, башни выше облаков, клинки, которые передают из поколения в поколение. Цех не терпит спешки: здесь годами учатся класть один камень и ковать один клинок, пока рука не перестанет ошибаться.","Вы — подмастерье такого цеха. Вы помните тысячу одинаковых ударов, после которых мастер впервые кивнул, и знаете, что настоящая работа начинается там, где другие бросают. Ваша мечта велика, как сама гора: возвести то, чего не строил никто, или выковать оружие из оружий — вещь, о которой будут говорить, когда ваше имя забудут. Рузд с их быстрыми чудесами цех считает выскочками, что нарушают порядок Строителя, — а вы втайне гадаете, сколько в их чудесах мастерства, а сколько удачи."],
