    play: "Черта «Рука Строителя» — дисциплина вместо чудес: ещё два инструмента (каменщика и на выбор), результат к20 не ниже 10 при неспешной работе инструментом и устойчивость к толчкам и падениям. Анализ и Ловкость рук — глаз и рука мастера. Хорош для воина, паладина и изобретателя. Пара с «Учеником Рузды»: дисциплина и работа на века против быстрых чудес; оба владеют инструментами кузнеца."
