    enoaLead: ["Вы работали в мастерской рузды, мастера-изобретателя, чей титул передавался ученику за умение обращаться с металлом. Вы разбирали неисправные устройства, готовили детали, поддерживали огонь и сравнивали чертёж с тем, что получалось на верстаке. Тяжёлая заготовка требовала силы, мелкое соединение — ловкости, а поиск причины сбоя — знания материала и магических принципов. Наставник учил проверять замысел работой, сохраняя полезное даже в неудачной попытке. Вы освоили простые устройства и начальные магические приёмы, не присваивая себе всего искусства рузды. Станет ли титул вашим и как сложатся отношения с другими цехами, оставалось будущим, а не свершившимся фактом."],
    loreContext: ["Рузда — не имя, а титул: так джабари называют мастеров-изобретателей, учеников Сальбара. Рузда умеет то, что другим кажется чудом: собрать из металла и обломков доспех, оружие или механизм, каких никто прежде не видел, заставить механизм работать там, где он не должен, и найти в чужой работе слабое место с одного взгляда. Их творения, как и творения их учителя, — хаос, неопределённость и красота. Многое из того, что осталось от прошлых веков, вышло из рук рузд: редкие диковины, оружие, даже Врата, связавшие дальние земли. Титул передаётся не по крови, а по рукам: рузда выбирает того, чьи руки понимают металл, и не спрашивает, какого тот народа.","Вас выбрали. Вы можете быть кем угодно — джабари, человеком, худдулином, — но вы живёте в мастерской рузды, среди недоделанных чудес и чертежей на стенах, учитесь его ремеслу и, возможно, однажды примете титул. Не все этому рады. Цеха Строителя считают рузд разрушителями порядка, который держит Гендин. Чидкур, старик перевалов, ненавидит всех, кто связан с Сальбаром и руздами: они нарушают естественный порядок врат и связей. А родня рузды, если вы не джабари, так и не простила ему выбора."],
