    play: "Черта «Ремесло рузды» — изобретательность вместо дисциплины: заговор «Меткий удар» или «Защита от оружия» на Интеллекте и одно устройство за отдых на выбор — наруч-щит, крюк-кошка, осколочная шашка или магнитная ловушка. Аркана и Природа — знание металла и того, что из него можно собрать. Ближе всего к изобретателю, хорош также для воина и плута. Подходит любому народу. Пара с «Подмастерьем Звезды»; Чидкур ненавидит рузд — готовый конфликт с «Угодившим Чидкуру»."
