    glossary: ['poisoned-phb', 'reaction-phb', 'disadvantage-phb'],
    enoaLead: ["Вы пережили встречу с Чидкуром у перевала и сохранили память о ночи, когда обычное застолье стало чем-то большим. До неё или после вы работали с напитками: готовили сырьё, следили за брожением, переносили сосуды и проверяли, что подаёте путникам. Инструменты пивовара требовали знания состава, тяжёлая работа — силы, долгие посиделки — выдержки и умения разговаривать с разными людьми. Шутка порой прекращала ссору раньше угрозы, и вы учились выбирать для неё момент. Рассказы о старике и крысе Маге сопровождали перевалы, но подробности вашей встречи не требовали гибели спутников или заранее назначенного страха."],
    loreContext: ["Чидкур — хранитель врат, перевалов и долов: вечно пьяный кривозубый старик, у которого во рту живёт крыса Мага. Он куда умнее, чем кажется, и обмануть его трудно, а угодить — куда легче, поэтому путники перед перевалом разливают спирт и сыплют зерно. Про Чидкура поют песни и ставят комедии по всему Даскару. Немногие знают, что тех, кто ему не угодил, старик потрошит и оставляет Маге.","Вы встретили его в караван-сарае у перевала — или он встретил вас. Кривозубый старик подсел к огню, достал бутылку и предложил выпить за дорогу. Пили до утра, потом до следующего, потом вы сбились со счёта: пели, плясали на столах, ставили на кон сапоги и имена. Ваши спутники падали один за другим и больше не вставали. К концу у огня остались трое: вы, старик и крыса. Старик хлопнул вас по плечу, назвал собутыльником и ушёл в долину. Как вы выжили, вы толком не помните. Помните только, что было весело — и от этого страшнее всего."],
