    glossary: ['frightened-phb', 'creature-type-phb', 'study-phb'],
    enoaLead: ["Вы выполняли поручения ковена Меридиров среди смертных, разыскивая людей, вещи и сведения, которыми интересовался хозяин. Вы меняли облик с помощью грима, наблюдали за встречами, сравнивали слухи и изучали обычаи, позволявшие войти в нужный круг. Ловкие движения помогали оставаться незаметным, внимание — различать важную подробность, а уверенная речь — поддерживать правдоподобную роль. Служба учила замечать признаки чужой силы и помнить цену ошибки. Зависимость от ковена могла оставаться тяжёлой частью вашей жизни, однако она не определяла заранее каждое решение персонажа. Как вы понимали долг, страх или возможность освобождения, раскрывалось уже в игре."],
    loreContext: ["Есть те, кто старше городов и помнит время, когда у мира ещё не было имени. Они ходят среди смертных, носят любые лица и говорят на любых языках, и никто не оглядывается им вслед. Сами они никогда не выходят на свет. Для этого у них есть такие, как вы.","Вы принадлежите ковену. Не служите за плату и не присягали по доброй воле — принадлежите, как принадлежит вещь. Где бы вы ни были, ваша жизнь в руках хозяина, и вы чувствуете это всегда: в каждом шаге, в каждом встречном взгляде, который задерживается на вас чуть дольше обычного. Вы — глаза и руки ковена среди смертных: разыскиваете, приносите, добываете. Слухи и имена, чужие узлы и старые вещи, сведения о тех, кто светится ярче прочих, и о тех, кто задаёт о ковене слишком много вопросов.","Вы видели хозяина: обычное лицо, которое не запомнишь в толпе. Видели и то, что бывает с теми, кто ослушался, — и потому не ослушаетесь. Иногда вам кажется, что ковен голоден. Вы стараетесь об этом не думать."],
