    enoaLead: ["Вы жили с синевой, проступавшей на коже, и семейной книгой, чьи непонятные знаки переписывали из поколения в поколение. Вы учились владеть пером, сверяли страницы и искали в старых рассказах следы Тусуса, с которым предание связывало необычную кровь. Долгие поиски требовали терпения, работа с книгой — памяти, а внимание посторонних — умения отвечать твёрдо и не выдавать больше желаемого. Вы наблюдали за своим телом, отделяя знакомые особенности от чужих домыслов. Наследственный дар оставался источником необычной стойкости, но приобретённые знания возникли из труда и общения. Ваше отношение к легенде не было обязано совпадать с ожиданиями семьи."],
    loreContext: ["Есть миф, который помнят разве что редкие одиночки. В нём говорится о Тусусе — короле, которого сказание зовёт то Королём людей, то Королём крови. Он правил городом, от которого не осталось даже имени, носил золотое лицо вместо своего, и кровь его была синей, как ночное небо. Свою кровь он раздавал детям — и забирал обратно. Король пал, город ушёл в топь, а кровь осталась: растеклась по чужим родам и уснула в них на века. Иногда она просыпается.","В вас она проснулась. Синева наплывает на вашу кожу пятнами — медленно, как тень от облака, и с годами растекается дальше. Что это, не знает никто: лекари разводят руками, жрецы отводят глаза. Многим это кажется страшным, и куда бы вы ни пришли, на вас смотрят — пристально, долго, не скрываясь. Дети показывают пальцем, старики шепчут обереги, торговцы диковинами предлагают цену. А вы замечаете, что ни разу в жизни серьёзно не болели и что чужая воля соскальзывает с вас, как вода. Книга в вашем мешке — семейная: её исписали знаками, которые в роду переписывают из поколения в поколение, хотя прочесть их давно никто не умеет."],
